import axios from "axios";
import React, { useState, useEffect } from "react";
import "./App.css";

const App = () => {
  const [data, setData] = useState([]);
  const [filteredData, setFilteredData] = useState([]);
  <table className="table-auto w-full border">
  <thead>
    <tr>
      <th>Date</th>
      <th>Revenue</th>
      <th>Net Income</th>
      <th>Gross Profit</th>
      <th>EPS</th>
      <th>Operating Income</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td>2024-09-28</td>
      <td>1000000</td>
      <td>500000</td>
      <td>600000</td>
      <td>1.23</td>
      <td>400000</td>
    </tr>
  </tbody>
</table>
;
  const [sort, setSort] = useState({ field: '', order: 'asc' });

  useEffect(() => {
    const fetchData = async () => {
      const apiKey = '8N8rcH4ELi16WYr8FyL0M4yknkwFQeRC';
      const url = `https://financialmodelingprep.com/api/v3/income-statement/AAPL?period=annual&apikey=8N8rcH4ELi16WYr8FyL0M4yknkwFQeRC`;
      try {
        const response = await axios.get(url);
        console.log("Fetched Data:", response.data);
        console.log("Filtered Data:", filteredData);
        setData(response.data);
        setFilteredData(response.data);
      } catch (error) {
        console.error('Error fetching data:', error);
      }
      if (filteredData.length === 0) {
        return <div>No data available to display.</div>;
      }

    };
    fetchData();
  }, []);

  // Other component logic...

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">Apple Financial Data</h1>
      <p>Debug: Rendering is working!</p>
    </div>
  );

};

export default App;
